action.mutation:
mutation CreateWorkcenter($payload: [WorkcenterCreatePayloadInput!]!) {
  mutation: createWorkcenter(payload: $payload) { 
    id
    code
  }
}

mutation UpdateWorkcenter($payload: [WorkcenterUpdatePayloadInput!]!) {
  mutation: updateWorkcenter(payload: $payload) { 
    id
    code
  }
}
